import sqlite3
import pytest
from solution import find_user

# Helper to create an in-memory database with a users table

def create_db_with_users(users):
    conn = sqlite3.connect(":memory:")
    conn.execute("CREATE TABLE users (id INTEGER PRIMARY KEY, username TEXT, email TEXT)")
    conn.executemany("INSERT INTO users (id, username, email) VALUES (?, ?, ?)", users)
    conn.commit()
    return conn

@pytest.fixture
def db():
    users = [
        (1, "alice", "alice@example.com"),
        (2, "bob", "bob@example.com"),
    ]
    return create_db_with_users(users)

def test_find_existing_user(db):
    result = find_user(db, "alice")
    assert result == {"id": 1, "username": "alice", "email": "alice@example.com"}

def test_find_nonexistent_user(db):
    result = find_user(db, "charlie")
    assert result is None

def test_find_user_empty_username(db):
    result = find_user(db, "")
    assert result is None

def test_find_user_none_username(db):
    with pytest.raises(TypeError):
        find_user(db, None)

# Ensure that the function does not modify the database

def test_no_side_effect(db):
    find_user(db, "bob")
    cursor = db.execute("SELECT COUNT(*) FROM users")
    count = cursor.fetchone()[0]
    assert count == 2

